(ns pm.diff-test
  "Differential test: replay diff/cases.json (generated by running the real
  prosemirror-model 1.25.13 / prosemirror-transform 1.12.7 under Node) through
  the Clojure port and compare every observable result.

  Generate the reference first:  cd diff && npm ci && node gen.mjs SEED COUNT
  Not part of the default runner (needs Node); run with `clojure -M:diff`."
  (:require [clojure.data.json :as json]
            [clojure.java.io :as io]
            [clojure.test :refer [deftest is testing]]
            [pm.model.mark :as mark]
            [pm.model.node :as node]
            [pm.schema.basic :refer [schema]]
            [pm.transform :as t]
            [pm.transform.map :as tmap]))

(def cases-file (io/file "diff/cases.json"))

(defn- load-cases []
  (when-not (.exists cases-file)
    (throw (ex-info "diff/cases.json missing: run `cd diff && npm ci && node gen.mjs 1 400`" {})))
  (json/read-str (slurp cases-file) :key-fn keyword))

(defn- norm
  "JSON equality as JS sees it: integral doubles equal integers. Explicit null
  is kept: {:value nil} and {} are different JSON and must not compare equal
  (the port models JS `undefined` as an absent key, like JSON.stringify)."
  [x]
  (cond (map? x) (into {} (map (fn [[k v]] [k (norm v)])) x)
        (sequential? x) (mapv norm x)
        (and (number? x) (== x (Math/rint (double x)))) (long x)
        :else x))

(defn- ->doc [j] (node/from-json schema j))

(defn- msg
  "Exception message, never nil (JVM exceptions such as IndexOutOfBounds carry none)."
  [^Throwable e]
  (or (ex-message e) (.getName (class e))))

(defn- fractional?
  "True if a step JSON carries a non-integral number in a position field. JS
  accepts these and computes garbage; the port deliberately rejects them
  (see README, Differences). Such cases are checked for rejection only."
  [step]
  (some (fn [k] (let [v (get step k)] (and (number? v) (not (== v (Math/rint (double v)))))))
        [:from :to :pos :gapFrom :gapTo :insert]))

(defn- replay
  "Run one case through the port, mirroring runCase in gen.mjs.
  Returns {:start :per [...] :mapped [...] :step-map :merges [...]}."
  [c]
  (let [doc (try (let [d (->doc (:doc c))] (node/check d) d) (catch Exception e {:threw (msg e)}))]
    (if (:threw doc)
      {:start doc}
      (loop [doc doc steps (:steps c) per [] parsed []]
        (if-let [sj (first steps)]
          (let [step (try (t/step-from-json schema sj) (catch Exception e {:threw (msg e) :stage "parse"}))]
            (if (:threw step)
              {:per (conj per {:status "threw" :stage "parse" :reason (:threw step)}) :parsed parsed}
              (let [res (try (t/apply-step step doc) (catch Exception e {:threw (msg e)}))]
                (cond
                  (:threw res) {:per (conj per {:status "threw" :stage "apply" :reason (:threw res)}) :parsed parsed}
                  (:failed res) {:per (conj per {:status "failed" :reason (:failed res)}) :parsed parsed}
                  :else
                  (let [new-doc (:doc res)
                        rec {:status "ok" :doc (node/to-json new-doc)
                             :map (:ranges (t/get-map step))
                             :roundTrip (t/step-to-json step)
                             :inverse (try (t/step-to-json (t/invert-step step doc)) (catch Exception _ ::threw))
                             :check (try (node/check new-doc) true (catch Exception e (msg e)))}]
                    (recur new-doc (next steps) (conj per rec) (conj parsed {:step step :before doc})))))))
          {:per per :parsed parsed})))))

(defn- mapped-table [parsed]
  (let [mapping (tmap/mapping (map #(t/get-map (:step %)) parsed))
        size (min 40 (reduce + 0 (map node/node-size (:content (:before (first parsed))))))]
    (vec (for [pos (range 0 (inc size)) assoc [-1 1]
               :let [m (tmap/map-result mapping pos assoc)]]
           [pos assoc (:pos m) (tmap/deleted? m) (tmap/deleted-before? m)
            (tmap/deleted-after? m) (tmap/deleted-across? m)]))))

(defn- rejected? [p] (#{"failed" "threw"} (:status p)))

(defn- compare-case [c]
  (let [mine (replay c) theirs (:per c) problems (atom [])
        bad! (fn [what detail] (swap! problems conj {:id (:id c) :what what :detail detail}))]
    (cond
      (some fractional? (:steps c))
      (when-not (some rejected? (:per mine))
        (bad! :fractional-accepted "port applied a step with a non-integral position"))

      (:threw (:start c)) (when-not (:threw (:start mine)) (bad! :start "JS rejected the start doc; port accepted it"))
      (:threw (:start mine)) (bad! :start (str "port rejected the start doc: " (:threw (:start mine))))
      :else
      (do
        (when (not= (count theirs) (count (:per mine)))
          (bad! :step-count {:js (count theirs) :port (count (:per mine))}))
        (doseq [[js me i] (map vector theirs (:per mine) (range))]
          (cond
            (not= (rejected? js) (rejected? me))
            (bad! :accept-vs-reject {:step i :js (select-keys js [:status :reason]) :port (select-keys me [:status :reason])})

            (= "ok" (:status js))
            (do (when-not (= (norm (:doc js)) (norm (:doc me))) (bad! :doc {:step i}))
                (when-not (= (norm (:map js)) (norm (:map me))) (bad! :step-map {:step i :js (:map js) :port (:map me)}))
                (when-not (= (norm (:roundTrip js)) (norm (:roundTrip me))) (bad! :round-trip {:step i}))
                (let [js-inv (if (:inverseThrew js) ::threw (norm (:inverse js)))]
                  (when-not (= js-inv (norm (:inverse me)))
                    (bad! :inverse {:step i :js js-inv :port (:inverse me)})))
                (when-not (= (:check js) (:check me)) (bad! :check {:step i :js (:check js) :port (:check me)}))))
          (when (and (= "failed" (:status js)) (= "failed" (:status me)) (not= (:reason js) (:reason me)))
            (bad! :failure-message {:step i :js (:reason js) :port (:reason me)})))
        (when (and (seq (:parsed mine)) (= (count theirs) (count (:parsed mine))))
          (when-not (= (norm (:mapped c)) (norm (mapped-table (:parsed mine))))
            (bad! :mapping {}))
          (when (> (count (:parsed mine)) 1)
            (let [rest (tmap/mapping (map #(t/get-map (:step %)) (rest (:parsed mine))))
                  mapped (try (some-> (t/map-step (:step (first (:parsed mine))) rest) t/step-to-json)
                              (catch Exception e ::threw))]
              (when-not (= (norm (:stepMap c)) (norm mapped))
                (bad! :step-map-over {:js (:stepMap c) :port mapped}))))
          (doseq [[i js] (map-indexed vector (:merges c))
                  :let [a (nth (:parsed mine) i) b (nth (:parsed mine) (inc i))
                        m (try (some-> (t/merge-steps (:step a) (:step b)) t/step-to-json) (catch Exception _ ::threw))]]
            (when-not (= (norm js) (norm m)) (bad! :merge {:step i :js js :port m}))))))
    @problems))

(deftest differential
  (let [data (load-cases)
        problems (vec (mapcat compare-case (:cases data)))
        by-kind (frequencies (map :what problems))]
    (println "reference versions:" (:versions data) " seed:" (:seed data))
    (println "stats:" (:stats data))
    (println "cases:" (count (:cases data)) " mismatches:" (count problems) by-kind)
    (doseq [p (take 15 problems)] (println "  MISMATCH" (pr-str p)))
    (is (empty? problems))))
